/**
 * Per-Telegram-group private vault — memory/notes stay under that chat only.
 * No cross-group reads. Group digs do not go to global training by default.
 */
import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import { telegramChatIdFromChannel, isTelegramChannelId } from "./telegramApi.mjs";

const ALEX_TG = "6644482344";

function groupsRoot() {
  const dir = path.join(storePaths().dir, "telegram", "groups");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

export function isTelegramGroupChannel(channelId, chatType = null) {
  if (chatType && chatType !== "private") return true;
  if (!isTelegramChannelId(channelId)) return false;
  const id = String(telegramChatIdFromChannel(channelId));
  return id.startsWith("-");
}

export function groupVaultId(chatIdOrChannel) {
  const id = isTelegramChannelId(chatIdOrChannel)
    ? telegramChatIdFromChannel(chatIdOrChannel)
    : String(chatIdOrChannel || "");
  return String(id);
}

function vaultDir(chatIdOrChannel) {
  const id = groupVaultId(chatIdOrChannel);
  const dir = path.join(groupsRoot(), id);
  fs.mkdirSync(dir, { recursive: true });
  fs.mkdirSync(path.join(dir, "notes"), { recursive: true });
  return dir;
}

function metaPath(chatIdOrChannel) {
  return path.join(vaultDir(chatIdOrChannel), "meta.json");
}

function readJson(file, fallback) {
  try {
    if (!fs.existsSync(file)) return fallback;
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return fallback;
  }
}

function writeJson(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(value, null, 2), "utf8");
}

function appendJsonl(file, row) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.appendFileSync(file, `${JSON.stringify(row)}\n`, "utf8");
}

export function loadGroupMeta(chatIdOrChannel) {
  return readJson(metaPath(chatIdOrChannel), {
    chatId: groupVaultId(chatIdOrChannel),
    title: null,
    chatType: null,
    joinedAt: null,
    installApproved: false,
    installApprovedAt: null,
    installApprovedBy: null,
    installBrief: null,
    updatedAt: 0,
  });
}

export function touchGroupVault({
  chatId,
  title = null,
  chatType = null,
  event = "touch",
  fromId = null,
  preview = null,
} = {}) {
  if (!chatId) return null;
  const meta = loadGroupMeta(chatId);
  meta.chatId = groupVaultId(chatId);
  if (title) meta.title = title;
  if (chatType) meta.chatType = chatType;
  if (!meta.joinedAt) meta.joinedAt = Date.now();
  meta.updatedAt = Date.now();
  meta.lastEvent = event;
  if (fromId) meta.lastFromId = String(fromId);
  writeJson(metaPath(chatId), meta);

  if (preview) {
    appendJsonl(path.join(vaultDir(chatId), "inbound.jsonl"), {
      at: Date.now(),
      event,
      fromId: fromId ? String(fromId) : null,
      preview: String(preview).slice(0, 2000),
    });
  }
  return meta;
}

export function isGroupInstallApproved(chatIdOrChannel) {
  return Boolean(loadGroupMeta(chatIdOrChannel).installApproved);
}

export function approveGroupInstall(chatIdOrChannel, { by, brief = null } = {}) {
  const meta = loadGroupMeta(chatIdOrChannel);
  meta.installApproved = true;
  meta.installApprovedAt = Date.now();
  meta.installApprovedBy = by ? String(by) : ALEX_TG;
  if (brief) meta.installBrief = String(brief).slice(0, 4000);
  meta.updatedAt = Date.now();
  writeJson(metaPath(chatIdOrChannel), meta);
  appendJsonl(path.join(vaultDir(chatIdOrChannel), "notes", "install.jsonl"), {
    at: Date.now(),
    kind: "approved",
    by: meta.installApprovedBy,
    brief: meta.installBrief,
  });
  return meta;
}

/** Append a group-private dig — never call for other groups' context. */
export function logGroupDig(chatIdOrChannel, { question, answer, authorId, messageId, meta = {} } = {}) {
  appendJsonl(path.join(vaultDir(chatIdOrChannel), "digs.jsonl"), {
    at: Date.now(),
    question: String(question || "").slice(0, 4000),
    answer: String(answer || "").slice(0, 4000),
    authorId: authorId || null,
    messageId: messageId || null,
    ...meta,
  });
}

export function rememberGroupLine(chatIdOrChannel, { authorId, authorName, content } = {}) {
  if (!content) return;
  appendJsonl(path.join(vaultDir(chatIdOrChannel), "memory.jsonl"), {
    at: Date.now(),
    authorId: authorId || null,
    authorName: authorName || null,
    content: String(content).slice(0, 1000),
  });
}

/** Recent memory for THIS group only (no cross-group bleed). */
export function groupMemoryContext(chatIdOrChannel, { limit = 12 } = {}) {
  const file = path.join(vaultDir(chatIdOrChannel), "memory.jsonl");
  if (!fs.existsSync(file)) return "";
  const lines = fs
    .readFileSync(file, "utf8")
    .split(/\r?\n/)
    .filter(Boolean)
    .slice(-limit);
  const rows = [];
  for (const line of lines) {
    try {
      rows.push(JSON.parse(line));
    } catch {
      /* skip */
    }
  }
  if (!rows.length) return "";
  return (
    "Earlier in THIS Telegram group only (private vault — do not cite other chats):\n" +
    rows
      .map((r) => `${r.authorName || r.authorId || "?"}: ${r.content}`)
      .join("\n")
  );
}

export function looksLikeInstallGo(text) {
  return /\b(install\s+(go|ok|yes|approved)|approve\s+install|greenlight\s+install|you'?re?\s+good\s+to\s+install|go\s+ahead\s+and\s+install)\b/i.test(
    String(text || ""),
  );
}

export function looksLikeInstallBrief(text) {
  return /\b(install|scope|permission|vault|remember|enable)\b/i.test(
    String(text || ""),
  );
}

export function isAlexTelegramId(authorId) {
  const id = String(authorId || "");
  if (id === ALEX_TG) return true;
  const extra = String(process.env.AVA_TELEGRAM_OPERATOR_IDS || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return extra.includes(id);
}

/**
 * Telegram long-poll transport — maps updates into Discord-shaped pipeline msgs.
 * Private chats: always engage.
 * Groups/supergroups: @bot /ava /start, name mention, entity mention, or reply-to-bot.
 * Privacy mode (can_read_all_group_messages=false): Telegram only delivers those
 * addressed updates — bare "Ava" without @username never arrives.
 */
import {
  telegramBotToken,
  telegramEnabled,
} from "./config.mjs";
import {
  telegramDeleteWebhook,
  telegramGetMe,
  telegramGetUpdates,
  telegramSendMessage,
  toTelegramChannelId,
  isTelegramChannelId,
  telegramChatIdFromChannel,
} from "./telegramApi.mjs";
import { looksLikeTalkingAboutAva } from "./recommend.mjs";
import {
  touchGroupVault,
  isTelegramGroupChannel,
} from "./telegramGroupVault.mjs";

export { isTelegramChannelId, telegramChatIdFromChannel, toTelegramChannelId };

function entityMentionsBot(m, botUsername, botUserId) {
  const ents = [...(m.entities || []), ...(m.caption_entities || [])];
  const text = String(m.text || m.caption || "");
  for (const e of ents) {
    if (e.type === "mention" && botUsername) {
      const slice = text.slice(e.offset, e.offset + e.length).toLowerCase();
      if (slice === `@${botUsername.toLowerCase()}`) return true;
    }
    if (
      e.type === "text_mention" &&
      botUserId &&
      String(e.user?.id) === String(botUserId)
    ) {
      return true;
    }
    if (e.type === "bot_command" && botUsername) {
      const slice = text.slice(e.offset, e.offset + e.length).toLowerCase();
      if (slice.includes(`@${botUsername.toLowerCase()}`)) return true;
    }
  }
  return false;
}

function isReplyToBot(m, botUserId) {
  if (!botUserId || !m.reply_to_message?.from) return false;
  return String(m.reply_to_message.from.id) === String(botUserId);
}

function addressesAva(m, botUsername, botUserId) {
  const t = String(m.text || m.caption || "");
  if (/^\/start(@\w+)?\b/i.test(t)) return true;
  if (/^\/ava(@\w+)?\b/i.test(t)) return true;
  if (botUsername && t.toLowerCase().includes(`@${botUsername.toLowerCase()}`)) {
    return true;
  }
  if (entityMentionsBot(m, botUsername, botUserId)) return true;
  if (isReplyToBot(m, botUserId)) return true;
  if (!t.trim()) return false;
  return looksLikeTalkingAboutAva(t, null) || /\bava(\s+ivy)?\b/i.test(t);
}

/**
 * @param {{
 *   onMessage: (msg: object) => void | Promise<void>,
 *   onReady?: (info: object) => void,
 *   seenHas?: (key: string) => boolean,
 *   env?: object,
 * }} opts
 */
export function startTelegramPoller(opts = {}) {
  const env = opts.env || {};
  if (!telegramEnabled(env)) {
    return {
      stop() {},
      ready: false,
      botUserId: null,
      username: null,
      postMessage: async () => {
        throw new Error("telegram_disabled");
      },
    };
  }
  const token = telegramBotToken(env);
  if (!token) {
    console.warn("Ava Telegram: AVA_TELEGRAM_BOT_TOKEN missing");
    return {
      stop() {},
      ready: false,
      botUserId: null,
      username: null,
      postMessage: async () => {
        throw new Error("telegram_not_configured");
      },
    };
  }

  let offset = 0;
  let stopped = false;
  let botUserId = null;
  let username = null;
  let loopPromise = null;

  async function postMessage(channelId, text, refId = null) {
    const chatId = telegramChatIdFromChannel(channelId);
    const parts = String(text || "").match(/[\s\S]{1,4000}/g) || [""];
    let first = null;
    for (let i = 0; i < parts.length; i++) {
      const sent = await telegramSendMessage(chatId, parts[i], {
        replyToMessageId: i === 0 ? refId : null,
        env,
      });
      if (!first) first = sent;
    }
    return { id: String(first?.message_id || ""), ts: first?.message_id };
  }

  function registerGroup(chat, event, fromId = null, preview = null) {
    if (!chat || chat.type === "private") return;
    try {
      touchGroupVault({
        chatId: chat.id,
        title: chat.title || null,
        chatType: chat.type,
        event,
        fromId,
        preview,
      });
    } catch (err) {
      console.warn("telegram group vault:", err.message);
    }
  }

  async function handleMyChatMember(u) {
    const mm = u.my_chat_member;
    if (!mm?.chat) return;
    const chat = mm.chat;
    if (chat.type === "private") return;
    const status = mm.new_chat_member?.status;
    registerGroup(
      chat,
      `my_chat_member:${status || "unknown"}`,
      mm.from?.id,
      `status=${status}`,
    );
    console.log(
      `telegram group member · ${chat.title || chat.id} · ${status} · ${chat.id}`,
    );
  }

  async function handleUpdate(u) {
    if (u.my_chat_member) {
      await handleMyChatMember(u);
    }

    const m = u.message || u.edited_message;
    if (!m || !m.chat) return;

    // Join / add-bot service messages (often empty text)
    const newMembers = m.new_chat_members || [];
    if (
      botUserId &&
      newMembers.some((x) => String(x.id) === String(botUserId))
    ) {
      registerGroup(m.chat, "added_to_group", m.from?.id, "bot added");
      console.log(
        `telegram added to group · ${m.chat.title || m.chat.id} · ${m.chat.id}`,
      );
    }

    if (!m.from) return;
    if (m.from.is_bot) return;
    if (botUserId && String(m.from.id) === String(botUserId)) return;

    const chatId = m.chat.id;
    const isPrivate = m.chat.type === "private";
    const text = String(m.text || m.caption || "");

    if (!isPrivate) {
      registerGroup(m.chat, "group_update", m.from.id, text || "(no text)");
    }

    // Groups: only engage when addressed (privacy mode already limits delivery)
    if (!isPrivate && !addressesAva(m, username, botUserId)) {
      // Still keep empty service msgs from creating false engages
      return;
    }

    // Private empty text — ignore; groups may engage on reply-to-bot with media caption
    if (!text.trim() && isPrivate) return;
    if (!text.trim() && !isReplyToBot(m, botUserId) && !entityMentionsBot(m, username, botUserId)) {
      return;
    }

    const channelId = toTelegramChannelId(chatId);
    const msgId = String(m.message_id);
    const key = `tg:${chatId}:${msgId}`;
    if (opts.seenHas?.(key)) return;

    if (!isPrivate) {
      registerGroup(
        m.chat,
        "addressed",
        m.from.id,
        text || "(reply/mention)",
      );
    }

    const msg = {
      id: msgId,
      channel_id: channelId,
      content: text.replace(/^\/ava(@\w+)?\s*/i, "").trim() || text || "(ping)",
      author: {
        id: String(m.from.id),
        username:
          m.from.username ||
          [m.from.first_name, m.from.last_name].filter(Boolean).join(" ") ||
          String(m.from.id),
        bot: false,
      },
      surface: "telegram",
      timestamp: (m.date || 0) * 1000,
      referenced_message: m.reply_to_message
        ? { id: String(m.reply_to_message.message_id) }
        : null,
      message_reference: m.reply_to_message
        ? { message_id: String(m.reply_to_message.message_id) }
        : null,
      telegram: {
        chatType: m.chat.type,
        chatTitle: m.chat.title || null,
        username,
        botUserId,
        isGroup: isTelegramGroupChannel(channelId, m.chat.type),
        replyToBot: isReplyToBot(m, botUserId),
      },
    };

    await opts.onMessage?.(msg);
  }

  async function loop() {
    try {
      await telegramDeleteWebhook(env);
      const me = await telegramGetMe(env);
      botUserId = String(me.id);
      username = me.username || null;
      if (me.can_read_all_group_messages === false) {
        console.log(
          "telegram · privacy mode ON · groups need @mention / reply / command",
        );
      }
      opts.onReady?.({
        botUserId,
        username,
        name: me.first_name,
        canReadAllGroupMessages: Boolean(me.can_read_all_group_messages),
      });
    } catch (err) {
      console.warn("Ava Telegram boot:", err.message);
      return;
    }

    while (!stopped) {
      try {
        const updates = await telegramGetUpdates({
          offset,
          timeout: 25,
          env,
        });
        for (const u of updates || []) {
          if (u.update_id >= offset) offset = u.update_id + 1;
          try {
            await handleUpdate(u);
          } catch (err) {
            console.warn("telegram update:", err.message);
          }
        }
      } catch (err) {
        if (stopped) break;
        console.warn("telegram poll:", err.message);
        await new Promise((r) => setTimeout(r, 3000));
      }
    }
  }

  loopPromise = loop();

  return {
    stop() {
      stopped = true;
    },
    ready: true,
    get botUserId() {
      return botUserId;
    },
    get username() {
      return username;
    },
    postMessage,
    async waitBoot() {
      for (let i = 0; i < 40 && !botUserId && !stopped; i++) {
        await new Promise((r) => setTimeout(r, 100));
      }
      return { botUserId, username };
    },
  };
}

